arguments.command:
curl -s -X POST "https://slack.com/api/conversations.list?token=<TOKEN>&types=public_channel,private_channel&limit=1000" | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'):
    print('ERROR', d.get('error'), d.get('error_summary',''))
    sys.exit(0)
for c in d['channels']:
    if 'incident' in c['name'] or 'payment' in c['name'] or 'oncall' in c['name'] or 'on-call' in c['name']:
        print(c['id'], c['name'], 'is_private:', c.get('is_private'))
"

